r"""plugin 的 hook（plugins\pcces\hooks\hooks.json 掛 PostToolUse 與 PostToolUseFailure）：pcces_ 工具在同一個 session
連續回錯 2 次，就在工具結果旁附一段提醒，請模型照 pcces skill〈使用回報〉問使用者要不要寫一筆使用回報。

Claude Code 2.1.322 實測：MCP 工具回 isError 觸發的是 PostToolUseFailure、成功的才觸發 PostToolUse
（notes〈使用回報的 hook 事件與計數〉）。失敗累加、成功歸零，只有累加到剛好 2 那一次提醒，同一串錯不重複提醒；
使用者中止（is_interrupt）不算錯。計數存在 %TEMP%\pcces_report_hook\<session_id>：一次失敗附加一個位元組、
用附加後的位置當次數（不讀舊值再寫回，平行的兩次失敗不會互蓋），成功就刪檔。
hook 不准擋住使用者的 session：任何例外都吞掉、退出碼一律 0、沒事就不印。
"""

from __future__ import annotations

import json
import os
import re
import sys
import tempfile
from pathlib import Path

THRESHOLD = 2
STATE_DIR_NAME = "pcces_report_hook"
_UNSAFE = re.compile(r"[^A-Za-z0-9_-]")


def is_pcces_tool(name: object) -> bool:
    """MCP 工具名是 mcp__<server>__<tool>（plugin 的是 mcp__plugin_pcces_pcces__<tool>）；只認工具那段以 pcces_ 開頭的。"""
    return isinstance(name, str) and name.startswith("mcp__") and name.rsplit("__", 1)[-1].startswith("pcces_")


def state_file(session_id: object, base: Path) -> Path | None:
    sid = _UNSAFE.sub("", str(session_id or ""))[:80]
    return base / sid if sid else None


def hint(tool: str) -> str:
    short = tool.rsplit("__", 1)[-1]
    return (f"PCCES 工具在這個 session 已經連續 {THRESHOLD} 次回錯（最近一次是 {short}）。"
            "照 pcces skill〈使用回報〉：先把手上這一步收在適合停的地方，再用一句話問使用者要不要寫一筆使用回報，"
            "同意才叫 pcces_report_issue；這個問題已經問過、或使用者說過不要，就不要再問。"
            "參數打錯、改一次就好的錯不必問。")


def _bump(f: Path) -> int:
    f.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(f, os.O_WRONLY | os.O_CREAT | os.O_APPEND | getattr(os, "O_BINARY", 0))
    try:
        os.write(fd, b"x")
        return os.lseek(fd, 0, os.SEEK_CUR)
    finally:
        os.close(fd)


def handle(payload: dict, base: Path) -> dict | None:
    """回要印到 stdout 的 JSON（hookSpecificOutput.additionalContext），不必提醒就回 None。"""
    tool = payload.get("tool_name")
    if not is_pcces_tool(tool):
        return None
    f = state_file(payload.get("session_id"), base)
    if f is None:
        return None
    event = payload.get("hook_event_name")
    if event == "PostToolUse":
        f.unlink(missing_ok=True)
        return None
    if event != "PostToolUseFailure" or payload.get("is_interrupt"):
        return None
    if _bump(f) != THRESHOLD:
        return None
    return {"hookSpecificOutput": {"hookEventName": "PostToolUseFailure", "additionalContext": hint(tool)}}


def main() -> int:
    try:
        payload = json.loads(sys.stdin.buffer.read().decode("utf-8"))
        out = handle(payload, Path(tempfile.gettempdir()) / STATE_DIR_NAME) if isinstance(payload, dict) else None
    except Exception as exc:  # noqa: BLE001 hook 壞了也不能卡住使用者；exit 0 的 stderr 模型看不到，只進 --debug 紀錄
        print(f"pcces report hook: {exc!r}", file=sys.stderr)
        return 0
    if out:
        sys.stdout.write(json.dumps(out))  # ensure_ascii：中文寫成 \u 跳脫，不管 stdout 是哪種編碼都讀得回
    return 0


if __name__ == "__main__":
    sys.exit(main())
